from utils.local_adapter import LocalDHFAdapter
from compliantflow.core import CompliantFlowCore

core = CompliantFlowCore\(LocalDHFAdapter\(Path\("DHF"\)\)\)
all_items = {i["id"]: i for i in core.get_all_items\(\)}
G = core.graph.graph

def get_prefix\(type_code\):
    if core.config:
        t = core.config.get_type\(type_code\)
        if t:
            return t.id_prefix
    return f"{type_code}-"

def check_downstream_coverage\(parent_type, child_type\):
    parent_prefix = get_prefix\(parent_type\)
    child_prefix = get_prefix\(child_type\)
    uncovered = []
    for node in G.nodes:
        if node.startswith\(parent_prefix\):
            children = [n for n in G.predecessors\(node\) if n.startswith\(child_prefix\)]
            if not children:
                uncovered.append\(node\)
    return uncovered

for parent, child in [\("UC", "CRS"\), \("CRS", "SYS"\), \("SYS", "SYSARCH"\)]:
    uncovered = check_downstream_coverage\(parent, child\)
    status = "OK" if not uncovered else "FAIL"
    print\(f"[{status}] {parent}→{child}: {len\(uncovered\)} uncovered" + \(f": {uncovered}" if uncovered else ""\)\)
EOF)

